$rows=db()->query('SELECT * FROM services ORDER BY sort_order,id')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Services | Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand" href="dashboard.php">Distinguished Web Services</a><a class="btn btn-outline-light btn-sm" href="logout.php">Logout</a></div></nav><main class="container py-5"><div class="d-flex justify-content-between mb-4"><h1>Services</h1><a class="btn btn-primary" href="service-form.php">Add Service</a></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Service</th><th>Order</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=htmlspecialchars((string)($r['title']??''),ENT_QUOTES,'UTF-8')?></strong><div class="small text-muted"><?=htmlspecialchars((string)($r['description']??''),ENT_QUOTES,'UTF-8')?></div></td><td><?=htmlspecialchars((string)($r['sort_order']??0),ENT_QUOTES,'UTF-8')?></td><td><?=((int)($r['is_active']??0)?'Active':'Inactive')?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="service-form.php?id=<?=$r['id']?>">Edit</a><form class="d-inline" method="post"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-secondary">Toggle</button></form><form class="d-inline" method="post" onsubmit="return confirm('Delete this service?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="4" class="text-center py-5 text-muted">No services yet.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>